// Autopilot's agents are OpenHands conversations, so every run keeps its
// transcript and diff in Canvas. This is the small REST driver the
// orchestrator uses to start, poll, nudge, pause and resume them on the agent
// server (1.55.1, reached through Canvas's ingress under /api).
//
// The conversation id is generated by the caller and saved before start(), so
// starting again after a restart is safe: the agent server answers 200 with
// the existing conversation instead of creating a second one.

export type ExecutionStatus = "idle" | "running" | "paused" | "waiting_for_confirmation" | "finished" | "error" | "stuck";
const STATUSES = new Set<string>(["idle", "running", "paused", "waiting_for_confirmation", "finished", "error", "stuck"]);

/** An agent profile. `server` is the ACP backend (claude-code, codex, …); null for native OpenHands agents. */
export interface AgentProfile {
  id: string;
  name: string;
  kind: string;
  server: string | null;
}

export interface ConversationSnapshot {
  id: string;
  status: ExecutionStatus | "unknown";
  costUsd: number; // the conversation's accumulated cost so far
  workingDir: string | null;
}

export interface StartInput {
  conversationId: string; // a UUID the caller generated and saved first
  profileId: string;
  workingDir: string; // absolute; the factory makes the worktree, not the agent server
  text: string; // the brief
  runId: string;
  role: string;
  seq?: number | null; // work order, for the tag
}

/** `status` is the HTTP status, or 0 when the agent server couldn't be reached. */
export class OpenHandsError extends Error {
  constructor(
    readonly status: number,
    message: string,
  ) {
    super(message);
    this.name = "OpenHandsError";
  }
}

interface RawMetrics {
  accumulated_cost?: unknown;
  metrics?: { accumulated_cost?: unknown } | null;
}
interface RawConversation {
  id: string;
  execution_status?: string;
  metrics?: RawMetrics | null;
  stats?: { usage_to_metrics?: Record<string, RawMetrics | null> } | null;
  workspace?: { working_dir?: string } | null;
}
interface RawProfile {
  id: string | null;
  name: string;
  agent_kind?: string;
  acp_server?: string | null;
}

const money = (v: unknown) => (typeof v === "number" && Number.isFinite(v) ? v : 0);

/**
 * Locally the agent server leaves `metrics` empty and keeps costs per LLM in
 * `stats.usage_to_metrics`, so sum those; take `metrics` when it says more.
 */
function costOf(info: RawConversation): number {
  const perLlm = Object.values(info.stats?.usage_to_metrics ?? {});
  const fromStats = perLlm.reduce((sum, m) => sum + money(m?.accumulated_cost ?? m?.metrics?.accumulated_cost), 0);
  return Math.max(money(info.metrics?.accumulated_cost), fromStats);
}

function snapshot(info: RawConversation): ConversationSnapshot {
  const status = info.execution_status ?? "";
  return {
    id: info.id,
    status: STATUSES.has(status) ? (status as ExecutionStatus) : "unknown",
    costUsd: costOf(info),
    workingDir: info.workspace?.working_dir ?? null,
  };
}

/** FastAPI errors carry `detail`: a string, or a list of validation errors. */
function detailOf(body: unknown): string | undefined {
  const detail = (body as { detail?: unknown } | null)?.detail;
  if (typeof detail === "string") return detail;
  if (Array.isArray(detail)) return detail.map((d) => (d as { msg?: string } | null)?.msg ?? JSON.stringify(d)).join("; ");
  return undefined;
}

const userMessage = (text: string) => ({ role: "user", content: [{ type: "text", text }], run: true });

export class OpenHandsClient {
  readonly baseUrl: string;
  private readonly apiKey: () => string | undefined;
  private readonly fetch: typeof fetch;
  private readonly timeoutMs: number;

  constructor(opts: { baseUrl: string; apiKey?: () => string | undefined; fetch?: typeof fetch; timeoutMs?: number }) {
    this.baseUrl = opts.baseUrl.replace(/\/+$/, "");
    this.apiKey = opts.apiKey ?? (() => undefined);
    this.fetch = opts.fetch ?? fetch;
    this.timeoutMs = opts.timeoutMs ?? 30_000;
  }

  private async request<T>(method: "GET" | "POST", path: string, body?: unknown): Promise<T> {
    const headers: Record<string, string> = {};
    const key = this.apiKey();
    if (key) headers["X-Session-API-Key"] = key;
    if (body !== undefined) headers["Content-Type"] = "application/json";
    let res: Response;
    let text: string;
    try {
      res = await this.fetch(`${this.baseUrl}/api${path}`, {
        method,
        headers,
        body: body === undefined ? undefined : JSON.stringify(body),
        signal: AbortSignal.timeout(this.timeoutMs),
      });
      text = await res.text();
    } catch (err) {
      const timedOut = err instanceof Error && err.name === "TimeoutError";
      throw new OpenHandsError(
        0,
        timedOut ? `Agent server at ${this.baseUrl} did not answer within ${this.timeoutMs} ms` : `Agent server unreachable at ${this.baseUrl}`,
      );
    }
    // Canvas's ingress answers 502/503/504 when the agent server behind it is down.
    if (res.status === 502 || res.status === 503 || res.status === 504) {
      throw new OpenHandsError(0, `Agent server unreachable at ${this.baseUrl} (HTTP ${res.status} from the proxy)`);
    }
    let data: unknown;
    try {
      data = JSON.parse(text);
    } catch {
      data = undefined;
    }
    if (!res.ok) throw new OpenHandsError(res.status, detailOf(data) ?? `HTTP ${res.status} from ${method} /api${path}`);
    // Every call answers JSON; anything else means the URL isn't the agent server.
    if (data == null) throw new OpenHandsError(res.status, `${method} /api${path} at ${this.baseUrl} did not answer with JSON; is it the agent server?`);
    return data as T;
  }

  /**
   * The listing leaves out which ACP backend a profile runs, so ACP profiles
   * are read one by one for it (critic and reviewer want another vendor).
   */
  async listProfiles(): Promise<{ profiles: AgentProfile[]; activeId: string | null }> {
    const list = await this.request<{ profiles: RawProfile[]; active_agent_profile_id: string | null }>("GET", "/agent-profiles");
    const profiles = await Promise.all(
      list.profiles
        .filter((p): p is RawProfile & { id: string } => !!p.id)
        .map(async (p): Promise<AgentProfile> => {
          const kind = p.agent_kind ?? "openhands";
          let server = p.acp_server ?? null;
          if (kind === "acp" && !server) {
            const detail = await this.request<{ profile?: RawProfile }>("GET", `/agent-profiles/${encodeURIComponent(p.name)}`).catch(() => null);
            server = detail?.profile?.acp_server ?? null;
          }
          return { id: p.id, name: p.name, kind, server };
        }),
    );
    return { profiles, activeId: list.active_agent_profile_id ?? null };
  }

  /**
   * `ref` is a profile id or name; none means Canvas's active profile. With
   * `avoidServerOf`, a profile on another ACP backend is preferred (the active
   * one if it qualifies), falling back to the active one.
   */
  async resolveProfile(ref?: string | null, opts: { avoidServerOf?: string | null } = {}): Promise<AgentProfile> {
    const { profiles, activeId } = await this.listProfiles();
    if (ref) {
      const found = profiles.find((p) => p.id === ref) ?? profiles.find((p) => p.name === ref);
      if (!found) throw new Error(`No agent profile "${ref}" on the agent server`);
      return found;
    }
    const active = profiles.find((p) => p.id === activeId) ?? profiles[0];
    if (!active) throw new Error("The agent server has no agent profiles");
    const avoid = opts.avoidServerOf;
    if (!avoid || active.server !== avoid) return active;
    return profiles.find((p) => p.server !== avoid) ?? active;
  }

  /** A stored profile's definition (profiles are secret-free at rest). */
  getProfile(name: string): Promise<{ name: string; profile: Record<string, unknown> }> {
    return this.request("GET", `/agent-profiles/${encodeURIComponent(name)}`);
  }

  /** Saves a profile under `name`; the server keeps its own id for it. */
  async saveProfile(name: string, profile: Record<string, unknown>): Promise<void> {
    await this.request("POST", `/agent-profiles/${encodeURIComponent(name)}`, profile);
  }

  start(input: StartInput): Promise<ConversationSnapshot> {
    return this.request<RawConversation>("POST", "/conversations", {
      conversation_id: input.conversationId,
      agent_profile_id: input.profileId,
      workspace: { kind: "LocalWorkspace", working_dir: input.workingDir },
      initial_message: userMessage(input.text),
      // The factory made the worktree; the agent server's own would branch from main.
      worktree: false,
      confirmation_policy: { kind: "NeverConfirm" },
      max_iterations: 500,
      stuck_detection: true,
      autotitle: false,
      tags: { sfrun: input.runId, sfrole: input.role, sfwo: input.seq == null ? "" : String(input.seq) },
      client_tools: [],
    }).then(snapshot);
  }

  /** null when the agent server doesn't know the conversation. */
  async get(id: string): Promise<ConversationSnapshot | null> {
    try {
      return snapshot(await this.request<RawConversation>("GET", `/conversations/${encodeURIComponent(id)}`));
    } catch (err) {
      if (err instanceof OpenHandsError && err.status === 404) return null;
      throw err;
    }
  }

  /** A follow-up user message; the agent starts working on it right away. */
  async send(id: string, text: string): Promise<void> {
    await this.request("POST", `/conversations/${encodeURIComponent(id)}/events`, userMessage(text));
  }

  async pause(id: string): Promise<void> {
    await this.request("POST", `/conversations/${encodeURIComponent(id)}/pause`);
  }

  /** Already running (409) counts as resumed. */
  async resume(id: string): Promise<void> {
    try {
      await this.request("POST", `/conversations/${encodeURIComponent(id)}/run`);
    } catch (err) {
      if (!(err instanceof OpenHandsError && err.status === 409)) throw err;
    }
  }

  /** The agent's last finish message or reply; "" when there is none yet. */
  async finalResponse(id: string): Promise<string> {
    const body = await this.request<{ response?: string }>("GET", `/conversations/${encodeURIComponent(id)}/agent_final_response`);
    return body?.response ?? "";
  }

  async ping(): Promise<{ ok: boolean; error?: string }> {
    try {
      await this.request("GET", "/agent-profiles");
      return { ok: true };
    } catch (err) {
      return { ok: false, error: err instanceof Error ? err.message : String(err) };
    }
  }
}

/**
 * What a polled conversation means for its attempt. Right after a message is
 * sent the server can still report the previous turn's end state, so an end
 * state counts only once the attempt has been seen running since that message
 * or the grace period has passed. ACP turns may end `idle` instead of `finished`.
 */
export function classify(
  snapshot: Pick<ConversationSnapshot, "status">,
  attempt: { seenRunning: boolean; lastSentAt: string },
  now: Date = new Date(),
  graceMs = 20_000,
): "running" | "done" | "failed" | "paused" {
  const settled = attempt.seenRunning || now.getTime() - Date.parse(attempt.lastSentAt) > graceMs;
  switch (snapshot.status) {
    case "finished":
    case "idle":
      return settled ? "done" : "running";
    case "error":
    case "stuck":
      return settled ? "failed" : "running";
    case "paused":
      return settled ? "paused" : "running";
    default:
      return "running";
  }
}
